using System.Text;
using System.Text.Json;
using MusicGen.Core.Text;

namespace MusicGen.Core.Tests;

/// <summary>
/// Reading files like Python's open(path, encoding="utf-8").read() (heartlib): strict UTF-8, BOM kept as U+FEFF and universal
/// newlines. The expected texts come from text_cases.json, generated by reading those same bytes with Python. Needs no checkpoint.
/// </summary>
public sealed class PythonTextReadTests : IDisposable
{
    private readonly string _dir = Directory.CreateTempSubdirectory("pytext-").FullName;
    public void Dispose() => Directory.Delete(_dir, recursive: true);

    private static List<(string name, byte[] bytes, string text)> FixtureCases()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(CoreFixtures.PathOf("text_cases.json")));
        return doc.RootElement.GetProperty("cases").EnumerateArray()
            .Select(c => (c.GetProperty("name").GetString()!, Convert.FromBase64String(c.GetProperty("bytes_b64").GetString()!), c.GetProperty("text").GetString()!))
            .ToList();
    }

    [Fact]
    public void AllFixtureCases_DecodeToExactlyWhatPythonRead()
    {
        var cases = FixtureCases();
        Assert.Equal(28, cases.Count);
        foreach (var (name, bytes, expected) in cases)
            Assert.True(expected == PythonText.DecodeText(bytes), $"{name}: the text read differs from Python's");
    }

    [Fact]
    public void Crlf_BecomesLf_AndLoneCrBecomesLf()
    {
        var path = Path.Combine(_dir, "crlf.txt");
        File.WriteAllBytes(path, Encoding.UTF8.GetBytes("a\r\nb\rc\nd\r\n"));

        Assert.Equal("a\nb\nc\nd\n", PythonText.ReadAllText(path));
        Assert.Contains("\r\n", File.ReadAllText(path));              // File.ReadAllText keeps them: that is the difference
    }

    [Fact]
    public void Bom_IsKeptAsU_FEFF_UnlikeFileReadAllText()
    {
        var path = Path.Combine(_dir, "bom.txt");
        File.WriteAllBytes(path, new byte[] { 0xEF, 0xBB, 0xBF }.Concat(Encoding.UTF8.GetBytes("hello")).ToArray());

        Assert.Equal("﻿hello", PythonText.ReadAllText(path));
        Assert.Equal("hello", File.ReadAllText(path));                // File.ReadAllText discards it
    }

    [Fact]
    public void InvalidUtf8_FailsExplicitly_NamingTheFile()
    {
        var path = Path.Combine(_dir, "bad.txt");
        File.WriteAllBytes(path, new byte[] { 0x68, 0xFF, 0xFE, 0x69 });

        var ex = Assert.Throws<InvalidDataException>(() => PythonText.ReadAllText(path));

        Assert.Contains("bad.txt", ex.Message);
        Assert.Contains("UTF-8", ex.Message);
    }

    [Fact]
    public void EmptyFile_IsAnEmptyString()
    {
        var path = Path.Combine(_dir, "empty.txt");
        File.WriteAllBytes(path, Array.Empty<byte>());

        Assert.Equal("", PythonText.ReadAllText(path));
    }
}
